+  private record RetainedMember(RetainedMemberType type, String className, String name, String descriptor) {
+    private static RetainedMember classMember(String className) {
+      return new RetainedMember(RetainedMemberType.CLASS, className, null, null);
+    }
+
+    private static RetainedMember field(String className, String name, String descriptor) {
+      return new RetainedMember(RetainedMemberType.FIELD, className, name, descriptor);
+    }
+
+    private static RetainedMember method(String className, String name, String descriptor) {
+      return new RetainedMember(RetainedMemberType.METHOD, className, name, descriptor);
+    }
+  }
+
+  /**
+   * Retention is shared by all ClassWriter instances used while one source file is written. Anonymous
+   * classes and lambda bodies create their own writers, but still contribute to the same output file.
+   */
+  private static final class ReferenceAwareRetention {
+    private final Set<ClassNode> processedNodes = Collections.newSetFromMap(new IdentityHashMap<>());
+    private final Set<ClassNode> failedNodes = Collections.newSetFromMap(new IdentityHashMap<>());
+    private final Set<RetainedMember> candidates = new HashSet<>();
+    private final Set<RetainedMember> retained = new HashSet<>();
+    private ImportCollector baseImports;
+
+    private void collectCandidates(ClassNode node) {
+      if (node.type != ClassNode.Type.LAMBDA) {
+        StructClass cl = node.classStruct;
+
+        if (node.type == ClassNode.Type.MEMBER && (node.hasModifier(CodeConstants.ACC_SYNTHETIC) || cl.isSynthetic())) {
+          candidates.add(RetainedMember.classMember(cl.qualifiedName));
+        }
+
+        for (StructField field : cl.getFields()) {
+          if (field.isSynthetic()) {
+            candidates.add(RetainedMember.field(cl.qualifiedName, field.getName(), field.getDescriptor()));
+          }
+        }
+
+        for (StructMethod method : cl.getMethods()) {
+          if (method.isSynthetic() || method.hasModifier(CodeConstants.ACC_BRIDGE)) {
+            candidates.add(RetainedMember.method(cl.qualifiedName, method.getName(), method.getDescriptor()));
+          }
+        }
+      }
+
+      for (ClassNode child : node.nested) {
+        collectCandidates(child);
+      }
+    }
+
+    private void initialize(ClassNode root) {
+      collectCandidates(root);
+      baseImports = new ImportCollector(DecompilerContext.getImportCollector());
+    }
+
+    private boolean isRetained(RetainedMember member) {
+      return retained.contains(member);
+    }
+
+    private void addReferences(TextBuffer buffer) {
+      int length = buffer.length();
+      for (TextToken token : buffer.getTokens()) {
+        // TextBuffer can retain token metadata for text removed with setLength/setStart. Such a token
+        // is not part of the emitted Java and must not affect the decision.
+        if (token.isDeclaration() || token.getStart() < 0 || token.getStart() + token.getLength() > length) {
+          continue;
+        }
+
+        RetainedMember member = null;
+        if (token instanceof ClassTextToken classToken) {
+          member = RetainedMember.classMember(classToken.qualifiedName);
+        } else if (token instanceof FieldTextToken fieldToken) {
+          member = RetainedMember.field(fieldToken.className, fieldToken.name, fieldToken.descriptor.descriptorString);
+        } else if (token instanceof MethodTextToken methodToken) {
+          member = RetainedMember.method(methodToken.className, methodToken.name, methodToken.descriptor.toString());
+        }
+
+        if (member != null && candidates.contains(member)) {
+          retained.add(member);
+        }
+      }
+    }
+
+    private ImportCollector newImportCollector() {
+      return new ImportCollector(baseImports);
+    }
+  }
